from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
m=Chem.MolFromSmiles('[Fe+2].[O-]C(C)=CC(C)=NCC1=CC=CC=N1.[N-]([Si](C)(C)C)[Si](C)(C)C')
rw=Chem.RWMol(m)
for i in (1,7,14,15): rw.AddBond(i,0,Chem.BondType.DATIVE)
m=rw.GetMol();Chem.SanitizeMol(m);m=Chem.AddHs(m)
p=AllChem.ETKDGv3();p.randomSeed=41832;p.maxIterations=500
assert AllChem.EmbedMolecule(m,p)==0
# Try UFF for pre-relaxation if parameters for Fe available
try:
 pms=AllChem.UFFGetMoleculeForceField(m)
 print('uff',pms.CalcEnergy())
except Exception as e: print('uff not found',e)
c=m.GetConformer();xyz=np.array(c.GetPositions());
for i in (1,7,14,15):
 v=xyz[i]-xyz[0];print('donor',i,'dist',np.linalg.norm(v), 'v',np.round(v,2))
print('N',m.GetNumAtoms())
for i in [1,7,14,15]:
 for j in [1,7,14,15]:
  if i<j:
   v=xyz[i]-xyz[0];w=xyz[j]-xyz[0];print(i,j,'angle',np.rad2deg(np.arccos(np.dot(v,w)/np.linalg.norm(v)/np.linalg.norm(w))))
with open('initial.xyz','w') as f:
 f.write(f'{m.GetNumAtoms()}\nFe pyridyl imino enolate bis(trimethylsilyl)amide initial\n')
 for a,p0 in zip(m.GetAtoms(),xyz):f.write(f'{a.GetSymbol()} {p0[0]:.7f} {p0[1]:.7f} {p0[2]:.7f}\n')
